package com.kiraworld.sarahtravel;
import android.app.Activity;import android.content.Intent;import android.graphics.Typeface;import android.os.Bundle;import android.widget.Button;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;
public final class HackathonDemoActivity extends Activity {
    @Override protected void onCreate(Bundle s){super.onCreate(s);ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(30,30,30,30);scroll.addView(r);add(r,"Sarah Travel OS — event demo",28,true);add(r,"1. Say: “I am stressed and this train feels too fast.” Sarah must keep the active traveler’s identity and offer train-aware calm choices.",16,false);add(r,"2. Ask Sarah to plan a New Zealand trip. With an approved Power Rangers interest saved to this exact profile, show proactive filming-location research, possible stops, facts and trivia.",16,false);add(r,"3. Open a source card, map, photos, video, route and accommodation handoff. Verify that Sarah distinguishes research from a confirmed booking.",16,false);add(r,"4. Let ElevenLabs speak the connected reply, then turn off internet and show Android speech, breathing, trivia, noticing games and public-domain songs.",16,false);add(r,"5. Pair the phone with the Windows companion, sync the conversation, trip and recent sanitized trip photos, and continue planning on the larger screen.",16,false);add(r,"6. Show SPOKEN, PRIVATE MIND and FACTUAL TRUTH separation in the private activity log without exposing private mind in chat or TTS.",16,false);Button sponsor=new Button(this);sponsor.setText("Show sponsor connections");sponsor.setOnClickListener(v->startActivity(new Intent(this,SponsorConnectionsActivity.class)));r.addView(sponsor);setContentView(scroll);SafeAreaInsets.apply(this,scroll,null,scroll);}private void add(LinearLayout r,String t,int size,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(size);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setPadding(0,10,0,8);r.addView(v);}
}
